rules.selector:
/* markdown, restyled: Young Serif h2, pencil-tick list markers, the blockquote as a teacher's note */
.pm.pmcd .pmcd-md{font-size:18px;line-height:1.7;color:color-mix(in srgb,var(--pm-ink) 84%,var(--pm-bone))}
.pm.pmcd .pmcd-md h2{margin:1.9em 0 .45em;font-size:clamp(30px,2.6vw,40px);font-weight:400;letter-spacing:-.02em;line-height:1.05;color:var(--pm-ink)} .pm.pmcd .pmcd-md h2:first-child{margin-top:0}
.pm.pmcd .pmcd-md ul{gap:12px;margin-top:1.2em} .pm.pmcd .pmcd-md li{padding-left:34px}
.pm.pmcd .pmcd-md li::before{top:.28em;width:22px;height:20px;border-radius:0;box-shadow:none;background:var(--pm-brass);-webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 22'><path d='M3 11 C 6 13, 8 16, 9.5 18.5 C 12 12, 16 6.5, 21.5 3' fill='none' stroke='black' stroke-width='2.8' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/contain no-repeat;mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 22'><path d='M3 11 C 6 13, 8 16, 9.5 18.5 C 12 12, 16 6.5, 21.5 3' fill='none' stroke='black' stroke-width='2.8' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/contain no-repeat}
.pm.pmcd .pmcd-md blockquote{position:relative;margin:1.6em 0;padding:18px 22px 18px 30px;border:0;border-radius:4px 14px 14px 4px;background:color-mix(in srgb,var(--pm-cloud) 70%,transparent);font-family:inherit;font-style:normal;font-size:clamp(21px,1.8vw,26px);line-height:1.35;rotate:-.6deg} .pm.pmcd .pmcd-md blockquote::before{content:"";position:absolute;left:10px;top:12px;bottom:12px;width:2px;border-radius:2px;background:var(--pm-brass)}
/* blocks */
.pmcd-bh{display:flex;align-items:baseline;justify-content:space-between;gap:20px;flex-wrap:wrap;padding-bottom:18px;border-bottom:1px solid color-mix(in srgb,var(--pm-ink) 14%,transparent)}
.pmcd-bh h2{margin:0;font-size:clamp(36px,3.4vw,52px);font-weight:400;line-height:1;letter-spacing:-.02em} .pmcd-bh p{margin:0;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--pm-mut)}
/* syllabus */
.pmcd-syl{--fill:clamp(0,calc((var(--sp,.5) - .18) / .42),1)} .pmcd.is-full .pmcd-syl{--fill:1}
.pmcd-sylw{position:relative}
.pmcd-rule{position:absolute;left:11px;top:24px;bottom:24px;width:2px;border-radius:2px;background:color-mix(in srgb,var(--pm-ink) 10%,transparent)} .pmcd-rule span{position:absolute;inset:0;border-radius:inherit;background:var(--pm-brass);transform-origin:50% 0;transform:scaleY(var(--fill))}
.pmcd-list{margin:0;padding:0;list-style:none}
.pmcd-row{border-bottom:1px solid color-mix(in srgb,var(--pm-ink) 9%,transparent)}
.pmcd-rowi{display:grid;grid-template-columns:24px 40px minmax(0,1fr) auto 56px;align-items:center;gap:14px;padding:20px 12px 20px 0;color:var(--pm-ink);text-decoration:none;border-radius:12px;transition:transform .45s cubic-bezier(.34,1.4,.64,1),background .3s}
.pmcd-row:hover .pmcd-rowi,.pmcd-rowi:focus-visible{transform:translateX(10px);background:color-mix(in srgb,var(--pm-cloud) 65%,transparent)}
.pmcd-dot{position:relative;display:grid;place-items:center;width:24px;height:24px} .pmcd-dot::before{content:"";width:10px;height:10px;border-radius:50%;background:var(--pm-bone);box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--pm-ink) 26%,transparent)}
.pmcd-dot i{position:absolute;width:10px;height:10px;border-radius:50%;background:var(--pm-brass);opacity:clamp(0,calc((var(--fill) - var(--i) / var(--n)) * 12),1);transform:scale(calc(.4 + .6 * clamp(0,calc((var(--fill) - var(--i) / var(--n)) * 12),1)))}
.pmcd-no{font-size:12px;letter-spacing:.06em;color:var(--pm-mut)}
.pmcd-lt{font-size:clamp(21px,1.7vw,24px);line-height:1.2;letter-spacing:-.01em}
.pmcd-ld{position:relative;font-size:12.5px;letter-spacing:.04em;font-variant-numeric:tabular-nums;color:color-mix(in srgb,var(--pm-ink) 72%,var(--pm-bone))}
.pmcd-ld svg{position:absolute;left:-2px;right:-2px;bottom:-7px;width:calc(100% + 4px);height:6px;overflow:visible} .pmcd-ld path{fill:none;stroke:var(--pm-brass);stroke-width:2.4;stroke-linecap:round;vector-effect:non-scaling-stroke;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset .45s cubic-bezier(.65,0,.25,1)} .pmcd-row:hover .pmcd-ld path,.pmcd-rowi:focus-visible .pmcd-ld path{stroke-dashoffset:0}
.pmcd-li{display:flex;justify-content:flex-end;color:var(--pm-mut)} .pmcd-free{padding:5px 9px;border-radius:8px;background:var(--pm-brass);color:var(--pm-ink);font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase}
/* kit: notebook checklist */
.pmcd-kit{--tk:clamp(0,calc((var(--sp,.5) - .2) / .36),1)} .pmcd.is-full .pmcd-kit{--tk:1}
.pmcd-note ul{margin:0;padding:0;list-style:none} .pmcd-note{position:relative;margin:30px 0 0;padding:26px 28px 22px 72px;border-radius:18px;background-color:var(--pm-cloud);box-shadow:0 30px 60px -40px rgba(23,21,15,.5),inset 0 0 0 1px color-mix(in srgb,var(--pm-ink) 7%,transparent);rotate:-.5deg}
.pmcd-note::before{content:"";position:absolute;left:48px;top:0;bottom:0;width:1.5px;background:color-mix(in srgb,var(--pm-brass) 70%,transparent)}
.pmcd-note li{display:flex;align-items:center;gap:16px;min-height:56px;font-size:17px;line-height:1.35;border-bottom:1px solid color-mix(in srgb,#5B8BB0 24%,transparent)} .pmcd-note li:last-child{border-bottom:0}
.pmcd-box{flex:none;width:26px;height:26px} .pmcd-box svg{width:100%;height:100%;overflow:visible} .pmcd-box path{fill:none;stroke:var(--pm-ink);stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.pmcd-box .pmcd-bt{stroke:var(--pm-brass);stroke-width:2.8;stroke-dasharray:1;stroke-dashoffset:calc(1 - clamp(0,(var(--tk) * var(--n) - var(--i)) * 1.4,1))}
/* teacher */
.pmcd-tg{display:grid;grid-template-columns:minmax(0,300px) minmax(0,1fr);gap:clamp(36px,4vw,64px);align-items:center;margin-top:40px}
.pmcd-pc{position:relative;display:block;padding:12px 12px 14px;border-radius:20px;background:var(--pm-cloud);text-decoration:none;color:var(--pm-ink);rotate:-2deg;box-shadow:0 30px 60px -38px rgba(23,21,15,.55),inset 0 0 0 1px color-mix(in srgb,var(--pm-ink) 7%,transparent);transition:rotate .6s cubic-bezier(.34,1.56,.64,1),translate .6s cubic-bezier(.34,1.56,.64,1)}
.pmcd-pc:hover,.pmcd-pc:focus-visible{rotate:0deg;translate:0 -6px}
.pmcd-port{aspect-ratio:4/5;width:100%;border-radius:12px} .pmcd-port .pmcd-skc{clip-path:circle(0% at 20% 90%);transition:clip-path 1.1s cubic-bezier(.65,0,.25,1)} .pmcd.is-one .pmcd-port .pmcd-skc{transition-duration:1.6s;transition-delay:.3s} .pmcd-pc:hover .pmcd-skc,.pmcd-pc:focus-visible .pmcd-skc,.pmcd.is-full .pmcd-port .pmcd-skc,.pmcd.is-one .pmcd-tch.is-seen .pmcd-skc{clip-path:circle(150% at 20% 90%)}
.pmcd-pcn{display:block;margin:12px 4px 0;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--pm-mut)}
.pmcd-tc{display:flex;flex-direction:column;align-items:flex-start;gap:18px}
.pmcd-q{position:relative;margin:0;padding:0} .pmcd-q p{margin:0;font-size:clamp(28px,2.6vw,40px);line-height:1.08;letter-spacing:-.02em}
.pmcd-qm{display:block;height:.5em;margin:0 0 6px -.04em;font-size:96px;line-height:.9;color:var(--pm-brass)}
.pmcd-bio{margin:0;max-width:460px;font-size:17px;line-height:1.55;color:color-mix(in srgb,var(--pm-ink) 78%,var(--pm-bone))}
.pmcd-ts{margin:0;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--pm-mut)}
/* enroll card */
.pmcd-card{position:relative;padding:30px 28px 26px;border-radius:22px;background:var(--pm-cloud);color:var(--pm-ink);rotate:-.8deg;box-shadow:0 40px 80px -44px rgba(23,21,15,.6),0 2px 0 color-mix(in srgb,var(--pm-ink) 6%,transparent),inset 0 0 0 1px color-mix(in srgb,var(--pm-ink) 7%,transparent);transition:rotate .7s cubic-bezier(.34,1.56,.64,1)}
.pmcd-card:hover,.pmcd-card:focus-within{rotate:0deg}
.pmcd-pl{margin:0;font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--pm-mut)}
.pmcd-price{margin:10px 0 0;font-size:56px;line-height:1;letter-spacing:-.025em}
.pmcd-aa{margin:10px 0 0;font-size:15px;color:color-mix(in srgb,var(--pm-ink) 74%,var(--pm-bone))} .pmcd-aa a{color:var(--pm-ink);text-underline-offset:3px;text-decoration-color:var(--pm-brass);text-decoration-thickness:1.5px}
.pmcd-btns{display:flex;flex-direction:column;gap:10px;margin-top:24px}
.pm.pmcd .pmcd-btns .pm-btn{display:flex;width:100%}
.pmcd-perks{display:flex;flex-direction:column;gap:12px;margin:24px 0 0;padding:22px 0 0;list-style:none;border-top:1px dashed color-mix(in srgb,var(--pm-ink) 18%,transparent)} .pmcd-perks li{display:flex;align-items:flex-start;gap:12px;font-size:15.5px;line-height:1.35}
.pmcd-tk{flex:none;width:20px;height:18px;margin-top:1px;overflow:visible} .pmcd-tk path{fill:none;stroke:var(--pm-brass);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:0}
.pmcd-proof{margin:20px 0 0;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--pm-mut)}
/* ---- night band ---- */
.pmcd-more{position:relative;background:var(--pm-night);color:var(--pm-cloud);padding:clamp(96px,10vw,150px) 0 clamp(110px,11vw,160px)}
.pmcd-mh{display:flex;align-items:flex-end;justify-content:space-between;gap:32px;flex-wrap:wrap}
.pmcd-mhh{margin:0;font-size:clamp(40px,4.3vw,64px);line-height:.98;letter-spacing:-.02em;font-weight:400} .pmcd-mhl{display:block}
.pmcd-more .pmcd-pen path{transition-delay:.4s}
.pmcd-mg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(28px,2.6vw,40px);margin:clamp(48px,5vw,72px) 0 0;padding:0;list-style:none}
.pmcd-mc{opacity:0;translate:0 40px;transition:opacity .9s ease var(--d),translate 1.1s cubic-bezier(.2,.8,.2,1) var(--d)} .pmcd-more.is-on .pmcd-mc,.pmcd.is-full .pmcd-mc{opacity:1;translate:0 0}
.pmcd-mci{position:relative;height:100%;display:flex;flex-direction:column;align-items:flex-start;padding:12px 12px 18px;border-radius:20px;background:var(--pm-bone);color:var(--pm-ink);rotate:var(--tl);box-shadow:0 30px 60px -34px rgba(0,0,0,.7);transition:rotate .55s cubic-bezier(.34,1.4,.64,1),translate .55s cubic-bezier(.34,1.4,.64,1)}
.pmcd-mc:hover .pmcd-mci,.pmcd-mc:focus-within .pmcd-mci{rotate:0deg;translate:0 -6px}
.pmcd-mph{width:100%;aspect-ratio:4/3;border-radius:12px} .pmcd-mph .pmcd-skc{clip-path:polygon(0 100%,100% 100%,100% 107.0%,91% 103.8%,80% 107.4%,69% 104.8%,57% 108.4%,45% 105.4%,33% 107.8%,21% 104.0%,10% 106.8%,0% 104.6%);transition:clip-path 1.6s cubic-bezier(.6,0,.25,1) calc(var(--d) + .5s)} .pmcd-more.is-on .pmcd-mph .pmcd-skc,.pmcd.is-full .pmcd-mph .pmcd-skc{clip-path:polygon(0 100%,100% 100%,100% -7.0%,91% -10.2%,80% -6.6%,69% -9.2%,57% -5.6%,45% -8.6%,33% -6.2%,21% -10.0%,10% -7.2%,0% -9.4%)}
.pmcd-msc{display:flex;align-items:center;gap:8px;width:100%;margin:16px 4px 0;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--pm-mut)} .pmcd-msc i{display:block;width:5px;height:5px;border-radius:50%;background:var(--pm-brass)} .pmcd-msc b{margin-left:auto;margin-right:8px;font-size:20px;font-weight:400;letter-spacing:-.01em;text-transform:none;color:var(--pm-ink)}
.pmcd-mt{margin:8px 4px 0;font-size:clamp(26px,2.1vw,30px);font-weight:400;line-height:1.04;letter-spacing:-.02em}
.pmcd-mw{margin:6px 4px 18px;font-size:15px;color:color-mix(in srgb,var(--pm-ink) 72%,var(--pm-bone))}
.pmcd-mci .pm-btn{margin:auto 4px 0}
/* ---- phone / tablet bar (portal) ---- */
.pmcd-bar{position:fixed!important;left:0;right:0;bottom:0;z-index:900!important;padding:0 10px calc(10px + env(safe-area-inset-bottom,0px));translate:0 120%;transition:translate .55s cubic-bezier(.2,.8,.2,1);pointer-events:none}
.pmcd-bar.is-on{translate:0 0;pointer-events:auto}
/* hidden bar = out of the tab order (inert + visibility, which flips only after the slide-out) */ .pmcd-bar:not(.is-on){visibility:hidden;transition:translate .55s cubic-bezier(.2,.8,.2,1),visibility 0s linear .55s}
.pmcd-bari{display:flex;align-items:center;justify-content:space-between;gap:14px;max-width:640px;margin:0 auto;padding:10px 10px 10px 18px;border-radius:18px;background:var(--pm-bone);color:var(--pm-ink);box-shadow:0 -6px 30px -12px rgba(23,21,15,.35),inset 0 0 0 1px color-mix(in srgb,var(--pm-ink) 10%,transparent)}
.pmcd-barp{display:flex;flex-direction:column;gap:2px;margin:0;min-width:0} .pmcd-barp b{font-size:28px;font-weight:400;line-height:1;letter-spacing:-.02em} .pmcd-barp span{font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--pm-mut);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pmcd-bar .pm-btn{flex:none}
/* ---- tablet / phone ---- */
.pmcd.is-one .pmcd-body{grid-template-columns:minmax(0,1fr);gap:72px;margin-top:80px}
.pmcd.is-one .pmcd-card{max-width:520px}
.pmcd.is-one .pmcd-main{max-width:none}
.pmcd.is-tab .pmcd-hero{grid-template-columns:minmax(0,1fr) minmax(0,.9fr);gap:40px;align-items:start}
.pmcd.is-tab .pmcd-h1{font-size:clamp(52px,7vw,72px)} .pmcd.is-tab .pmcd-big{min-height:0;max-height:none} .pmcd.is-tab .pmcd-proj{left:-24px;max-width:230px} .pmcd.is-tab .pmcd-pjn{display:none}
.pmcd.is-tab .pmcd-mg{grid-template-columns:repeat(2,minmax(0,1fr))} .pmcd.is-tab .pmcd-mc:nth-child(3){display:none}
.pmcd.is-ph .pmcd-paper{padding-top:100px;padding-bottom:80px}
.pmcd.is-ph .pmcd-hero{grid-template-columns:1fr;gap:56px} .pmcd.is-ph .pmcd-h1{font-size:clamp(44px,12.4vw,60px)} .pmcd.is-ph .pmcd-lead{font-size:17px}
.pmcd.is-ph .pmcd-big{min-height:0;max-height:none;aspect-ratio:4/4.4} .pmcd.is-ph .pmcd-ph{justify-self:stretch;padding:0 4px} .pmcd.is-ph .pmcd-proj{position:relative;left:auto;bottom:auto;margin:-48px 0 0 14px;max-width:84%} .pmcd.is-ph .pmcd-pjn{display:none}
.pmcd.is-ph .pmcd-body{margin-top:56px;gap:64px}
.pmcd.is-ph .pmcd-card{padding:26px 20px 22px}
.pmcd.is-ph .pmcd-rowi{grid-template-columns:20px 28px minmax(0,1fr) auto;gap:10px;padding:16px 6px 16px 0} .pmcd.is-ph .pmcd-li{grid-column:4;grid-row:1} .pmcd.is-ph .pmcd-ld{grid-column:3;grid-row:2;justify-self:start} .pmcd.is-ph .pmcd-rule{left:9px} .pmcd.is-ph .pmcd-dot{width:20px} .pmcd.is-ph .pmcd-lt{font-size:19px}
.pmcd.is-ph .pmcd-note{padding:18px 16px 14px 52px} .pmcd.is-ph .pmcd-note::before{left:34px} .pmcd.is-ph .pmcd-note li{font-size:16px}
.pmcd.is-ph .pmcd-tg{grid-template-columns:1fr;gap:36px} .pmcd.is-ph .pmcd-pc{max-width:300px}
.pmcd.is-ph .pmcd-mg{grid-template-columns:1fr;gap:40px}
.pmcd.is-ph .pmcd-md{font-size:17px}
@media (prefers-reduced-motion:reduce){.pmcd-wi{transform:none!important} .pmcd-pen path{stroke-dashoffset:0!important} .pmcd-mc{opacity:1!important;translate:none!important} .pmcd-edge{display:none}}

:where(.pm){position:relative;z-index:10} .pm,.pm *{box-sizing:border-box;min-width:0} .pm-sr{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip:rect(0 0 0 0)!important;white-space:nowrap!important;padding:0!important;margin:-1px!important;border:0!important} :where(.pm) a{color:inherit} html,body{overflow-x:clip}
:where(a[href],button,input,select,textarea,summary,[tabindex]:not([tabindex="-1"]),[role="button"]):focus-visible{outline:3px solid var(--pm-ink,#0E1014)!important;outline-offset:2px!important;box-shadow:0 0 0 2px var(--pm-bone,#F1EEE7)!important} :where(.pm-dark) :where(a[href],button,input,select,textarea,summary,[tabindex]:not([tabindex="-1"])):focus-visible{outline-color:var(--pm-cloud,#FFFFFF)!important;box-shadow:0 0 0 2px var(--pm-night,#0A0B0F)!important} :where(.pm-inring) :where(a[href],button):focus-visible{outline-offset:-4px!important;box-shadow:none!important} :where(.pm) :is(input:not([type=range]):not([type=checkbox]):not([type=radio]),textarea,select):focus-visible{outline:2px solid currentColor!important;outline-offset:2px!important;box-shadow:none!important} :where(.pm) textarea{resize:none} .pm-inring:focus-visible{outline-offset:-3px!important;box-shadow:none!important} html{scroll-padding-top:96px;scroll-padding-bottom:88px}
/* any other focusable (e.g. a keyboard-focusable scroll row) gets the kit ring, never the browser default */ :where(.pm) :focus-visible{outline:3px solid var(--pm-ink,#0E1014);outline-offset:2px} :where(.pm-dark) :focus-visible{outline-color:var(--pm-cloud,#FFFFFF)}
/* controls inside clipped / sideways-scrolling rows draw their ring INSIDE the control so overflow never cuts it */ :where(.pmfq-filt,.pmal-pills,.pmcl-pills,.pmil-pills,.pmsu-rail,.pmag-scroll,.pmrs-feed,.pmfq-row,.pmco-topics,.pmbl-pills,.pmcg-pills) :where(a[href],button,input,[tabindex]):focus-visible{outline-offset:-3px!important;box-shadow:none!important} :where(.pmfq-filt,.pmal-pills,.pmcl-pills,.pmil-pills,.pmsu-rail){scroll-padding-inline:24px}
.pm-btn{position:relative;display:inline-flex;min-height:52px;border-radius:14px;text-decoration:none;cursor:pointer;white-space:nowrap;font-size:13px;font-weight:600;letter-spacing:.01em;color:var(--fg);transition:transform .45s cubic-bezier(.34,1.56,.64,1)}
.pm-face{position:relative;display:inline-flex;align-items:center;gap:12px;width:100%;min-height:inherit;padding:6px 22px 6px 7px;border-radius:inherit;background:var(--face);box-shadow:inset 0 0 0 1px var(--rim),0 1px 0 color-mix(in srgb,var(--pm-cloud) 10%,transparent) inset,0 14px 30px -18px rgba(0,0,0,.55);transition:box-shadow .4s,background .4s}
.pm-chip{position:relative;display:grid;place-items:center;width:38px;height:38px;flex:none;border-radius:10px;background:var(--chip);color:var(--chipfg);overflow:hidden;transition:background .4s,color .4s,transform .5s cubic-bezier(.34,1.56,.64,1)} .pm-chip svg{position:absolute;width:17px;height:17px;transition:transform .55s cubic-bezier(.7,0,.2,1),opacity .3s} .pm-g2{transform:translateX(-26px);opacity:0}
.pm-btn:hover .pm-g1,.pm-btn:focus-visible .pm-g1{transform:translateX(26px) rotate(20deg);opacity:0} .pm-btn:hover .pm-g2,.pm-btn:focus-visible .pm-g2{transform:none;opacity:1} .pm-btn:hover .pm-chip,.pm-btn:focus-visible .pm-chip{background:var(--chip2);color:var(--chipfg2)}
.pm-lbl{position:static;display:inline-flex;flex-direction:column;justify-content:center;line-height:1.15} .pm-sub{display:block;font-size:10.5px;font-weight:500;letter-spacing:.02em;opacity:.75;margin-bottom:1px} .pm-chip{z-index:1}
.pm-face{overflow:hidden;isolation:isolate} .pm-face::after{content:"";position:absolute;left:14px;right:14px;bottom:5px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--hl) 0 var(--buf,34%),color-mix(in srgb,var(--fg) 18%,transparent) var(--buf,34%));opacity:.9;transition:opacity .3s;animation:pm-buf 3.2s ease-in-out infinite} @keyframes pm-buf{0%,100%{--buf:30%}50%{--buf:42%}} @property --buf{syntax:'<percentage>';inherits:false;initial-value:34%}
